add('showkontrol_get_live_deck','Read the exact deck from /state for live transport observation. Returns the deck and any supplied t, tick and epochMs values from the same state response.',{deck:z.number().int().min(1).max(8)},async ({deck})=>{
 const state=await call('GET','/state');
 if(!state || typeof state!=='object' || Array.isArray(state) || !Array.isArray(state.decks)) throw Error('Malformed /state response: expected an object with a decks array');
 if(state.decks.some(d=>!d || typeof d!=='object' || Array.isArray(d) || !Number.isInteger(d.n))) throw Error('Malformed /state response: each deck must have an integer n');
 const matches=state.decks.filter(d=>d.n===deck);
 if(!matches.length) throw Error(`Deck ${deck} is absent from /state`);
 if(matches.length!==1) throw Error(`Malformed /state response: duplicate deck ${deck}`);
 const result={deck:matches[0]};
 for(const key of ['t','tick','epochMs']) if(Object.hasOwn(state,key)) {
  if(typeof state[key]!=='number' || !Number.isFinite(state[key])) throw Error(`Malformed /state response: ${key} must be a number`);
  result[key]=state[key];
 }
 return result;
},readOnly);
