const composeTrackSchema=z.object({templateName:z.string().optional(),templateDonor:trackTemplateDonor.optional(),trackName:z.string().regex(/^[A-Za-z0-9 _-]*[A-Za-z0-9_-][A-Za-z0-9 _-]*$/).optional(),partName:z.string().regex(/^content\/[A-Za-z0-9_-]+\.sktl$/).optional(),existingPartName:z.string().min(1).optional(),layerOperations:layerOperationsSchema.optional(),audioClipEdits:audioClipEditsSchema.optional(),cueRemovals:composeCueRemovalsSchema.optional(),cueEdits:composeCueEditsSchema.optional(),graphSettingEdits:composeGraphSettingEditsSchema.optional(),cues:z.array(z.object({layer:z.number().int().nonnegative(),startMs:z.number().nonnegative(),lengthMs:z.number().positive(),label:z.string().min(1),donor:graphDonorSchema.nullable().optional(),mixedGraph:mixedGraphSchema.optional(),settings:z.array(z.union([z.object({nodeId:z.string().min(1),key:z.string().min(1),value:z.string()}),z.object({nodeIndex:z.number().int().nonnegative(),key:z.string().min(1),value:z.string()})])).optional(),patchSettings:z.array(patchSettingSchema).optional(),postPatchSettings:z.array(z.union([z.object({nodeId:z.string().min(1),key:z.string().min(1),value:z.string()}),z.object({nodeIndex:z.number().int().nonnegative(),key:z.string().min(1),value:z.string()})])).optional()})).max(100).optional(),donor:graphDonorSchema.optional(),set:z.object({name:z.string(),setName:z.string().min(1),createIfMissing:z.boolean().optional()}).optional()});
