add('showkontrol_copy_cue_graph_timeline_copy','Returns warnings for copied nodes with an explicitly stored stopped value, using destination cue and node IDs. Copy a fixture-supported cue graph from a standalone .sktl template into an empty cue in another .sktl copy. Inspect both files and supply both SHA-256 values. Node IDs are unique only within the target timeline; check the entire show for collisions before combining files. Supports groupin, trigger, action, Script processor, and OSC generator nodes. Script and OSC cue acceptance and execution are unverified. Rejects unsupported ID-like references outside explicitly opted-in opaque text, and rejects router targets. Validate in ShowKontrol.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),template:z.string(),templateSha256:z.string().length(64),sourceCueId:z.string().min(1),targetCueId:z.string().min(1),allowOpaqueNodeText:z.boolean().optional().describe('Preserve eligible Script or OSC text containing node-like IDs without remapping them; inspect the returned warnings. Defaults to false.')},copyCueGraphBetweenTimelines,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_copy_cue_graph_node_show_copy','Returns warnings for copied nodes with an explicitly stored stopped value, using destination cue and node IDs. Copy one fixture-supported graph node from a cue in a template show into a cue graph in a new target show copy. Inspect both shows first. No wires are copied; internal ID-like references outside explicitly opted-in opaque text are rejected. Validate the result in ShowKontrol.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),name:z.string(),cueId:z.string().min(1),template:z.string(),templateSha256:z.string().length(64),templateName:z.string(),templateCueId:z.string().min(1),nodeId:z.string().min(1),allowOpaqueNodeText:z.boolean().optional().describe('Preserve eligible Script or OSC text containing node-like IDs without remapping them; inspect the returned warnings. Defaults to false.')},copyCueGraphNodeShowCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_copy_patch_node_to_cue_show_copy','Returns warnings for copied nodes with an explicitly stored stopped value, using destination cue and node IDs. Copy an action, trigger, Script processor, or OSC generator from an inspected offline patch into a cue graph in a new show copy. No wires are copied; internal ID-like references outside explicitly opted-in opaque text are rejected. Script and OSC nodes use patch prototypes; cue acceptance and execution remain unverified.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),name:z.string(),cueId:z.string().min(1),template:z.string(),templateFormat:z.enum(['skf','skshow']),templateSha256:z.string().length(64),nodeId:z.string().min(1),allowOpaqueNodeText:z.boolean().optional().describe('Preserve eligible Script or OSC text containing node-like IDs without remapping them; inspect the returned warnings. Defaults to false.')},copyPatchNodeToCueShowCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_copy_patch_setting_to_cue_show_copy','Copy one setting from an offline patch action, trigger, Script processor, or OSC generator to a matching cue graph node in a new show copy. Inspect both files first. Matching node types do not prove action-category compatibility; values, dependencies and ShowKontrol acceptance remain unverified.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),name:z.string(),cueId:z.string().min(1),nodeId:z.string().min(1),template:z.string(),templateFormat:z.enum(['skf','skshow']),templateSha256:z.string().length(64),templateNodeId:z.string().min(1),key:z.string().min(1)},copyPatchSettingToCueShowCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_assemble_cue_graph_show_copy','Returns warnings for copied nodes with an explicitly stored stopped value, using destination cue and node IDs. Assemble 1–50 fixture-supported nodes and up to 100 pin-0 wires in a cue graph in a new offline show copy. Wire from/to are zero-based indices into nodes. A graph-free cue must be empty or whitespace-only. Inspect the source and each template first. Destination filesystem must support hard links. App acceptance and external dependencies remain unverified.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),name:z.string(),cueId:z.string().min(1),nodes:z.array(z.object({template:z.string(),templateSha256:z.string().length(64),templateName:z.string(),templateCueId:z.string().min(1),nodeId:z.string().min(1),allowOpaqueNodeText:z.boolean().optional().describe('Preserve eligible Script or OSC text containing node-like IDs without remapping them; inspect the returned warnings. Defaults to false.')})).min(1).max(50),wires:z.array(z.object({from:z.number().int().nonnegative(),to:z.number().int().nonnegative()})).max(100).default([])},assembleCueGraphShowCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_assemble_mixed_cue_graph_show_copy','Returns warnings for copied nodes with an explicitly stored stopped value, using destination cue and node IDs. Assemble 1–50 nodes from cue or patch templates and up to 100 supported or candidate pin-0 wires into a new offline show copy. Wire from/to are zero-based indices into nodes. Inspect the source and each template first. Destination filesystem must support hard links. Node behavior in cue graphs, external dependencies and app acceptance remain unverified.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),name:z.string(),cueId:z.string().min(1),nodes:z.array(z.discriminatedUnion('kind',[z.object({kind:z.literal('cue'),template:z.string(),templateSha256:z.string().length(64),templateName:z.string(),templateCueId:z.string().min(1),nodeId:z.string().min(1),allowOpaqueNodeText:z.boolean().optional().describe('Preserve eligible Script or OSC text containing node-like IDs without remapping them; inspect the returned warnings. Defaults to false.')}),z.object({kind:z.literal('patch'),template:z.string(),templateSha256:z.string().length(64),templateFormat:z.enum(['skf','skshow']),nodeId:z.string().min(1),allowOpaqueNodeText:z.boolean().optional().describe('Preserve eligible Script or OSC text containing node-like IDs without remapping them; inspect the returned warnings. Defaults to false.')})])).min(1).max(50),wires:z.array(z.object({from:z.number().int().nonnegative(),to:z.number().int().nonnegative()})).max(100).default([])},assembleMixedCueGraphShowCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_remove_cue_graph_node_copy','Remove an unreferenced cue graph node from a new offline timeline or show copy. Known ID references in supported parts are rejected; external systems and unrecognized parts are not checked. The check may reject harmless text. Inspect first and validate in ShowKontrol.',{source:z.string(),destination:z.string(),format:z.enum(['sktl','skshow']),sha256:z.string().length(64),name:z.string().optional(),cueId:z.string().min(1),nodeId:z.string().min(1)},removeCueGraphNodeCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_inspect_patch','Inspect nodes, connections and existing settings in an offline version 2 patch (.skf) or .skshow wrapper.',{file:z.string(),format:z.enum(['skf','skshow'])},inspectPatch,readOnly);
add('showkontrol_edit_patch_setting_copy','Change one existing application or node setting in an offline patch copy. Inspect first and supply its SHA-256. Values are strings; accepted values and application compatibility are not validated. The destination must not exist.',{source:z.string(),destination:z.string(),format:z.enum(['skf','skshow']),sha256:z.string().length(64),nodeId:z.string().optional().describe('Node ID; omit for an application setting'),key:z.string(),value:z.string()},editPatchSettingCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_edit_patch_graph_copy','Duplicate or remove a node, or add or remove a connection in an offline patch copy. Inspect first. Node removal requires all its connections to be removed first. It checks the remaining patch and supported .skf, .sktl, .sksc, .skls and .skpr show parts for ID text. Router removal also checks router target settings in those parts and rejects ambiguous router names. A standalone patch check covers that patch only. The check can reject harmless text; other parts and external references are not checked. Duplicates retain settings, title and position. Pin and node compatibility is not validated.',{source:z.string(),destination:z.string(),format:z.enum(['skf','skshow']),sha256:z.string().length(64),operation:z.enum(['duplicate_node','remove_node','add_connection','remove_connection']),nodeId:z.string().optional(),newNodeId:z.string().optional(),connection:z.object({fromNode:z.string(),fromPin:z.number().int().nonnegative(),toNode:z.string(),toPin:z.number().int().nonnegative()}).optional()},editPatchGraphCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_edit_patch_batch_copy','Apply 1–100 ordered setting, graph, and donor-node operations to an offline patch copy. Inspect all sources and supply their SHA-256 hashes. The destination must not exist. Removing a node deletes it from the offline copy; removal checks the remaining patch and supported .skf, .sktl, .sksc, .skls and .skpr show parts for ID text. The check can reject harmless text; other parts and external references are not checked. Node copies retain internal references and do not copy connections or dependencies. Values, compatibility and ShowKontrol acceptance are not validated.',{source:z.string(),destination:z.string(),format:z.enum(['skf','skshow']),sha256:z.string().length(64),operations:patchOperationsSchema},editPatchBatchCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_copy_patch_node','Copy one existing node from an offline template patch into a new offline destination patch copy. Inspect both files first. Copies node XML only; no connections or dependencies. The copied title, position, settings and internal references remain unchanged. Compatibility is not validated.',{source:z.string(),destination:z.string(),format:z.enum(['skf','skshow']),sha256:z.string().length(64),template:z.string(),templateFormat:z.enum(['skf','skshow']),templateSha256:z.string().length(64),nodeId:z.string(),newNodeId:z.string()},copyPatchNode,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_inspect_xml','Inspect an offline UTF-8 XML file and return its SHA-256 checksum and exact text. Do not use this to edit an active show.',{file:z.string()},inspectXml,readOnly);
add('showkontrol_edit_xml_copy','Apply exact unique text replacements to an offline XML file and write a new file. Requires the checksum from inspection. The source and all unmodified text are preserved. This validates XML syntax only, not ShowKontrol schema or compatibility.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),edits:z.array(z.object({find:z.string().min(1),replace:z.string()})).min(1)},editXmlCopy,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
add('showkontrol_inspect_show','Read an offline .skshow wrapper manifest and verify part MD5 checksums.',{file:z.string()},inspectShow,readOnly);
add('showkontrol_inspect_show_media','Inventory literal media.map mappings, archive parts and audio clips in track and Program item timelines; does not test playback or access external media.',{file:z.string()},inspectShowMedia,readOnly);
add('showkontrol_inspect_show_overview','Summarize an offline show from one consistent snapshot: parts, tracks, cues, set lists, patch nodes, and canonical Program items. Fails on invalid checksums or unsupported native structures. Program evidence is static and unverified.',{file:z.string()},inspectShowOverview,readOnly);
add('showkontrol_validate_show','Check an offline show snapshot for part checksums, duplicate node IDs, graph connections, set-track references and direct cue timing and layer fields. Unsupported or invalid parts can make checks incomplete. This does not validate pin compatibility or prove that ShowKontrol will load or run the show.',{file:z.string()},validateShow,readOnly);
add('showkontrol_read_show_part','Read a UTF-8 part from an offline .skshow file after verifying its MD5.',{file:z.string(),name:z.string()},readShowPart,readOnly);
add('showkontrol_read_show_part_page','Read a bounded page of a UTF-8 show part. Offsets count UTF-16 code units; use nextOffset for the next page and pass the returned sha256 to detect changes between pages. A page never splits a Unicode character.',{file:z.string(),name:z.string(),offset:z.number().int().nonnegative().default(0),limit:z.number().int().min(2).max(32768).default(16384),sha256:z.string().length(64).optional()},readShowPartPage,readOnly);
add('showkontrol_edit_show_part_copy','Edit one XML part of an offline .skshow file. Verify all part checksums and source SHA-256, update the edited part MD5, and write a new file. XML validity does not prove ShowKontrol compatibility.',{source:z.string(),destination:z.string(),sha256:z.string().length(64),name:z.string(),edits:z.array(z.object({find:z.string().min(1),replace:z.string()})).min(1)},editShowPart,{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false});
